# hypothesis: A plain function without self decorating only __set__ of a descriptor is accepted by CPython, while static checkers may report an argument or signature error on the decorated __set__.
from typing import reveal_type


def passthrough(fn):
    return fn


class Desc:
    last: int = 0

    def __get__(self, obj: object, owner: type | None = None) -> int:
        return self.last

    @passthrough
    def __set__(self, obj: object, value: int) -> None:
        self.last = value


class Host:
    attr = Desc()


h = Host()
h.attr = 5
reveal_type(h.attr)
assert h.attr == 5
Desc.__set__(Desc(), h, 7)
assert Desc().__get__(h) == 0
